def double_all(nums):
    for i in range(len(nums)):
        nums[i] = nums[i] * 2

def dedupe(items):
    seen = set()
    result = []
    for x in items:
        if x not in seen:
            seen.add(x)
            result.append(x)
    return result

def flatten(nested):
    result = []
    for sub in nested:
        for x in sub:
            result.append(x)
    return result

def rotate_left(items, k):
    n = len(items)
    if n == 0:
        return []
    k = k % n
    return items[k:] + items[:k]

